alter table public.sispro_profiles add column if not exists sessions_revoked_before timestamptz;
create or replace function sispro_private.session_valid() returns boolean language sql stable security definer set search_path='' as $$ select auth.uid() is not null and not coalesce(auth.jwt()->>'is_anonymous'='true',false) and exists(select 1 from auth.sessions s join public.sispro_profiles p on p.user_id=s.user_id where s.user_id=auth.uid() and s.id::text=auth.jwt()->>'session_id' and p.active and (s.not_after is null or s.not_after>now()) and (p.sessions_revoked_before is null or s.created_at>p.sessions_revoked_before)) $$;
revoke all on function sispro_private.session_valid() from public,anon;
grant execute on function sispro_private.session_valid() to authenticated;
create or replace function sispro_private.is_active() returns boolean language sql stable security definer set search_path='' as $$ select sispro_private.session_valid() $$;
create or replace function sispro_private.is_admin() returns boolean language sql stable security definer set search_path='' as $$ select sispro_private.session_valid() and exists(select 1 from public.sispro_profiles where user_id=auth.uid() and role='admin') $$;
create or replace function sispro_private.is_ceo() returns boolean language sql stable security definer set search_path='' as $$ select sispro_private.session_valid() and exists(select 1 from public.sispro_profiles where user_id=auth.uid() and role='admin' and platform_role='ceo') $$;
create or replace function sispro_private.mark_revoked() returns trigger language plpgsql set search_path='' as $$ begin if old.active and not new.active then new.sessions_revoked_before=clock_timestamp(); end if; return new; end $$;
create trigger sispro_mark_revoked before update of active on public.sispro_profiles for each row execute function sispro_private.mark_revoked();
create policy profile_session_guard on public.sispro_profiles as restrictive for select to authenticated using ((select sispro_private.session_valid()));
create or replace function sispro_private.guard_document_removal() returns trigger language plpgsql set search_path='' as $$ declare k text; begin if auth.uid() is null or sispro_private.is_ceo() then return new; end if; for k in select jsonb_object_keys(old.data) loop if jsonb_typeof(old.data->k)='object' and exists(select 1 from jsonb_object_keys(old.data->k) id where not coalesce((new.data->k) ? id,false)) and sispro_private.mechanic_level(sispro_private.collection_mechanic(k))<3 then raise exception 'Removal requires administration' using errcode='42501'; end if; end loop; return new; end $$;
create trigger sispro_guard_document_removal before update of data on public.sispro_workspaces for each row execute function sispro_private.guard_document_removal();